SELECT /* LGUTLC00300.retrieveApprovalPList */ submission_no ,request_master_id ,request_code ,org_id ,ou_short_name ,system_code ,module_code ,title ,request_date ,requestor_id ,requestor_emp_no ,requestor_emp_name ,requestor_name_eng ,status_code ,status_name ,all_pass_day ,my_pass_day FROM ( SELECT larn.request_no AS SUBMISSION_NO ,larn.request_master_id AS request_master_id ,larn.request_code AS request_code ,larn.organization_id AS org_id ,lcv.short_code AS ou_short_name ,lc_sys.code_data1_value AS system_code ,lc_mod.common_code_desc AS module_code ,larn.request_title AS title ,TO_CHAR(larn.request_date, 'yyyy-mm-dd hh24:mi') AS request_date ,larn.requestor_id AS requestor_id ,lumv.user_name AS requestor_emp_no ,lumv.full_name_local|| '/' ||NVL(lumv.position_name,lumv.title_name) || '/' || lumv.organization_name_eng AS requestor_emp_name ,lumv.english_full_name AS requestor_name_eng ,larn.status_code AS status_code ,lccc.common_code_desc AS status_name ,to_date(to_char(SYSDATE, 'yyyymmdd'),'yyyy-mm-dd') - to_date(to_char(larn.request_date, 'yyyymmdd'),'yyyy-mm-dd') AS all_pass_day ,( SELECT to_date(to_char(SYSDATE, 'yyyymmdd'),'yyyy-mm-dd') - to_date(to_char(aa.approval_date, 'yyyymmdd'),'yyyy-mm-dd') FROM lgcom_approval_status_n aa WHERE aa.request_master_id = larn.request_master_id AND aa.request_code = larn.request_code AND aa.approval_action_code IN ('REQUEST','APPROVAL','AGREEMENT', 'PARAGREE_ALL' , 'PARAGREE_OR' ) AND aa.approval_seqs = lasn.approval_seqs - 1 ) AS my_pass_day FROM lgcom_approval_request_n larn ,lgcom_approval_status_n lasn ,lgcom_company_v lcv ,lgcom_user_m_v lumv ,lgcom_common_code_c lccc ,lgcom_common_code_c lc_sys ,lgcom_common_code_c lc_mod WHERE 1 = 1 AND larn.system_code = lc_sys.common_code AND lc_sys.code_type_code = 'LGCOM_SYSTEM_CODE' AND larn.module_code = lc_mod.common_code AND larn.system_code = lc_mod.parent_common_code AND lc_mod.code_type_code = 'LGCOM_MODULE_CODE' AND larn.organization_id = lcv.organization_id AND larn.request_master_id = lasn.request_master_id AND larn.requestor_id = lumv.application_user_id AND larn.request_code = lasn.request_code AND larn.status_code IN ('20','30') AND lasn.approval_action_code IN ('APPROVAL', 'AGREEMENT', 'PARAGREE_ALL' ) AND larn.request_date BETWEEN to_date(#{dateFrom},'yyyy-mm-dd') AND to_date(#{dateTo},'yyyy-mm-dd') + 1 AND lasn.sign_user_no IS NULL AND lasn.approval_date IS NULL AND lasn.approval_status_code = '2' AND lccc.code_type_code = 'LGCOM_APPROVAL_REQ_STATUS_CODE' AND larn.status_code = lccc.common_code AND lasn.user_no = #{USER_SESSION.userName}
AND larn.requestor_id = #{requestorApplUserId}
AND larn.request_title like #{title} || '%'
UNION ALL SELECT larn.request_no AS SUBMISSION_NO ,larn.request_master_id AS request_master_id ,larn.request_code AS request_code ,larn.organization_id AS org_id ,lcv.short_code AS ou_short_name ,lc_sys.code_data1_value AS system_code ,lc_mod.common_code_desc AS module_code ,larn.request_title AS title ,TO_CHAR(larn.request_date, 'yyyy-mm-dd hh24:mi') AS request_date ,larn.requestor_id AS requestor_id ,lumv.user_name AS requestor_emp_no ,lumv.full_name_local|| '/' ||NVL(lumv.position_name,lumv.title_name) || '/' || lumv.organization_name_eng AS requestor_emp_name ,lumv.english_full_name AS requestor_name_eng ,larn.status_code AS status_code ,lccc.common_code_desc AS status_name ,to_date(to_char(SYSDATE, 'yyyymmdd'),'yyyy-mm-dd') - to_date(to_char(larn.request_date, 'yyyymmdd'),'yyyy-mm-dd') AS all_pass_day ,( SELECT to_date(to_char(SYSDATE, 'yyyymmdd'),'yyyy-mm-dd') - to_date(to_char(aa.approval_date, 'yyyymmdd'),'yyyy-mm-dd') FROM lgcom_approval_status_n aa WHERE aa.request_master_id = larn.request_master_id AND aa.request_code = larn.request_code AND aa.approval_action_code IN ('REQUEST','APPROVAL','AGREEMENT', 'PARAGREE_ALL' , 'PARAGREE_OR' ) AND aa.approval_seqs = lasn.approval_seqs - 1 ) AS my_pass_day FROM lgcom_approval_request_n larn ,lgcom_approval_status_n lasn ,lgcom_company_v lcv ,lgcom_user_m_v lumv ,lgcom_common_code_c lccc ,lgcom_common_code_c lc_sys ,lgcom_common_code_c lc_mod WHERE 1 = 1 AND larn.system_code = lc_sys.common_code AND lc_sys.code_type_code = 'LGCOM_SYSTEM_CODE' AND larn.module_code = lc_mod.common_code AND larn.system_code = lc_mod.parent_common_code AND lc_mod.code_type_code = 'LGCOM_MODULE_CODE' AND larn.organization_id = lcv.organization_id AND larn.request_master_id = lasn.request_master_id AND larn.requestor_id = lumv.application_user_id AND larn.request_code = lasn.request_code AND larn.status_code IN ('40') AND lasn.approval_action_code IN ('PARAGREE_OR') AND larn.request_date BETWEEN to_date(#{dateFrom},'yyyy-mm-dd') AND to_date(#{dateTo},'yyyy-mm-dd') + 1 AND lasn.sign_user_no IS NULL AND lasn.approval_date IS NULL AND lasn.approval_status_code = '2' AND lccc.code_type_code = 'LGCOM_APPROVAL_REQ_STATUS_CODE' AND larn.status_code = lccc.common_code AND lasn.user_no = #{USER_SESSION.userName}
AND larn.requestor_id = #{requestorApplUserId}
AND larn.request_title like #{title} || '%'
) ORDER BY request_date DESC

/* LGUTLC00300.retrieveApprovalCList */ SELECT larn.request_no AS SUBMISSION_NO ,larn.request_master_id AS request_master_id ,larn.request_code AS request_code ,larn.organization_id AS org_id ,lcv.short_code AS ou_short_name ,lc_sys.code_data1_value AS system_code ,lc_mod.common_code_desc AS module_code ,larn.request_title AS title ,TO_CHAR(larn.request_date, 'yyyy-mm-dd hh24:mi') AS request_date ,larn.requestor_id AS requestor_id ,lumv.user_name AS requestor_emp_no ,lumv.full_name_local|| '/' ||NVL(lumv.position_name,lumv.title_name) || '/' || lumv.organization_name_eng AS requestor_emp_name ,lumv.english_full_name AS requestor_name_eng ,larn.status_code AS status_code ,lccc.common_code_desc AS status_name ,to_date(to_char(lasn.approval_date, 'yyyymmdd'), 'yyyy-mm-dd') - to_date(to_char(larn.request_date, 'yyyymmdd'), 'yyyy-mm-dd') AS all_pass_day ,(SELECT to_date(to_char(lasn.approval_date, 'yyyymmdd'), 'yyyy-mm-dd') - to_date(to_char(tt.approval_date, 'yyyymmdd'), 'yyyy-mm-dd') FROM lgcom_approval_status_n tt WHERE tt.request_master_id = lasn.request_master_id AND tt.request_code = larn.request_code AND tt.approval_seqs = lasn.approval_seqs - 1 ) AS my_pass_day FROM lgcom_approval_request_n larn ,lgcom_approval_status_n lasn ,lgcom_company_v lcv ,lgcom_user_m_v lumv ,lgcom_common_code_c lccc ,lgcom_common_code_c lc_sys ,lgcom_common_code_c lc_mod WHERE 1 = 1 AND larn.system_code = lc_sys.common_code AND lc_sys.code_type_code = 'LGCOM_SYSTEM_CODE' AND larn.module_code = lc_mod.common_code AND larn.system_code = lc_mod.parent_common_code AND lc_mod.code_type_code = 'LGCOM_MODULE_CODE' AND larn.organization_id = lcv.organization_id AND larn.request_master_id = lasn.request_master_id AND larn.requestor_id = lumv.application_user_id AND larn.request_code = lasn.request_code AND larn.status_code IN ('20','30','40','50') AND lasn.approval_action_code IN ('APPROVAL', 'AGREEMENT', 'PARAGREE_ALL' , 'PARAGREE_OR' ) AND larn.request_date BETWEEN to_date(#{dateFrom},'yyyy-mm-dd') AND to_date(#{dateTo},'yyyy-mm-dd') + 1 AND lasn.approval_date IS NOT NULL AND lasn.approval_status_code IN ('3', '4') AND lccc.code_type_code = 'LGCOM_APPROVAL_REQ_STATUS_CODE' AND larn.status_code = lccc.common_code AND lasn.sign_user_no = #{USER_SESSION.userName}
AND larn.requestor_id = #{requestorApplUserId}
AND larn.request_title like #{title} || '%'
ORDER BY larn.request_date DESC, larn.last_update_date desc
